insert into detective_scenes(id, version_id, position, title, title_ar, image_path, introduction, introduction_ar) values ('f9a9fbc5-c136-575b-aca2-5e5df41f3da9', '99adb141-768d-5e89-b4cc-ec444728b6b5', 1, $q$The Display Gallery$q$, $q$قاعة العرض$q$, 'demo/detective/blue-ring-heist/scene-1.webp', $q$The cabinet is still standing in the center of the gallery. The velvet cushion is empty, yet the lock and frame look undamaged. A small blue mark and a paper slip may matter.$q$, $q$ما زالت الخزانة في وسط القاعة، لكن وسادة المخمل فارغة. يبدو القفل والإطار سليمين، بينما قد تكون لعلامة زرقاء صغيرة وورقة قرب المكتب أهمية في التحقيق.$q$) on conflict (id) do nothing;
insert into detective_evidence(id, scene_id, evidence_key, internal_title, public_title, public_title_ar, x, y, width, height, public_description, public_description_ar, admin_explanation, admin_explanation_ar, classification, importance, unlock_rule) values ('af567bc3-d75f-545a-a963-a7e9d94c3608', 'f9a9fbc5-c136-575b-aca2-5e5df41f3da9', $q$empty_cabinet$q$, $q$The empty velvet cushion$q$, $q$The empty velvet cushion$q$, $q$وسادة المخمل الفارغة$q$, 41, 20, 24, 32, $q$الخاتم غير موجود، لكن لا خدش ولا كسر على الخزانة. يبدو أن من فتحها استخدم مفتاحًا أو لمسة صحيحة، لا القوة.$q$, $q$الخاتم غير موجود، لكن لا خدش ولا كسر على الخزانة. يبدو أن من فتحها استخدم مفتاحًا أو لمسة صحيحة، لا القوة.$q$, $q$يثبت الاختفاء ويجعل فرضية اقتحام الخزانة بالقوة ضعيفة.$q$, $q$يثبت الاختفاء ويجعل فرضية اقتحام الخزانة بالقوة ضعيفة.$q$, $q$FACT$q$, 5, '{}'::jsonb) on conflict (id) do nothing;
insert into detective_evidence(id, scene_id, evidence_key, internal_title, public_title, public_title_ar, x, y, width, height, public_description, public_description_ar, admin_explanation, admin_explanation_ar, classification, importance, unlock_rule) values ('6248b016-e73b-5509-89e0-23104f2ecdb5', 'f9a9fbc5-c136-575b-aca2-5e5df41f3da9', $q$blue_wax_seal$q$, $q$Blue wax beside the latch$q$, $q$Blue wax beside the latch$q$, $q$شمع أزرق بجوار القفل$q$, 44, 53, 5, 5, $q$قطعة شمع فيروزية صغيرة عالقة أسفل القفل. ليست من لون الطلاء ولا من زينة الخاتم.$q$, $q$قطعة شمع فيروزية صغيرة عالقة أسفل القفل. ليست من لون الطلاء ولا من زينة الخاتم.$q$, $q$المادة تطابق فتات الشمع على قالب المفتاح في الورشة، وتربط العبث بالقفل بمكان إعداد قالب المفتاح.$q$, $q$المادة تطابق فتات الشمع على قالب المفتاح في الورشة، وتربط العبث بالقفل بمكان إعداد قالب المفتاح.$q$, $q$OBSERVATION$q$, 4, '{}'::jsonb) on conflict (id) do nothing;
insert into detective_evidence(id, scene_id, evidence_key, internal_title, public_title, public_title_ar, x, y, width, height, public_description, public_description_ar, admin_explanation, admin_explanation_ar, classification, importance, unlock_rule) values ('83aea0fc-9895-5152-af8e-b69646540b6b', 'f9a9fbc5-c136-575b-aca2-5e5df41f3da9', $q$inventory_slip$q$, $q$The folded inventory slip$q$, $q$The folded inventory slip$q$, $q$قصاصة سجل الجرد$q$, 59, 83, 25, 15, $q$على ظهر القصاصة توقيع استلام داخلي باسم نبيل، الساعة 8:42 مساءً، مع عبارة: «نقل مؤقت — صندوق الشحن».$q$, $q$على ظهر القصاصة توقيع استلام داخلي باسم نبيل، الساعة 8:42 مساءً، مع عبارة: «نقل مؤقت — صندوق الشحن».$q$, $q$تربط نبيل مباشرة بنقل الصندوق في الوقت الذي ادعى فيه أنه لم يقترب من المعرض بعد إغلاقه.$q$, $q$تربط نبيل مباشرة بنقل الصندوق في الوقت الذي ادعى فيه أنه لم يقترب من المعرض بعد إغلاقه.$q$, $q$FACT$q$, 4, '{}'::jsonb) on conflict (id) do nothing;
insert into detective_scenes(id, version_id, position, title, title_ar, image_path, introduction, introduction_ar) values ('6714c33e-a448-5bd9-9aec-660daebc7f57', '99adb141-768d-5e89-b4cc-ec444728b6b5', 2, $q$The Restoration Workshop$q$, $q$ورشة الترميم$q$, 'demo/detective/blue-ring-heist/scene-2.webp', $q$The workshop was used by Amina, the restorer, and by Nabil, the gallery assistant. A key-impression block, gloves and dispatch paperwork remain on the bench.$q$, $q$استخدمت أمينة الترميم الورشة، ودخلها أيضًا نبيل مساعد المعرض. بقي على الطاولة قالب لطبعة مفتاح وقفازات وأوراق شحن.$q$) on conflict (id) do nothing;
insert into detective_evidence(id, scene_id, evidence_key, internal_title, public_title, public_title_ar, x, y, width, height, public_description, public_description_ar, admin_explanation, admin_explanation_ar, classification, importance, unlock_rule) values ('598d6995-3324-5a56-b0a2-81b4771b2df9', '6714c33e-a448-5bd9-9aec-660daebc7f57', $q$key_impression$q$, $q$A fresh key impression$q$, $q$A fresh key impression$q$, $q$طبعة مفتاح حديثة$q$, 12, 58, 32, 23, $q$القالب يحمل تفاصيل تطابق مفتاح خزانة الخاتم. وعلى حافته أثر شمع أزرق مطابق للقطعة الموجودة قرب القفل.$q$, $q$القالب يحمل تفاصيل تطابق مفتاح خزانة الخاتم. وعلى حافته أثر شمع أزرق مطابق للقطعة الموجودة قرب القفل.$q$, $q$يشرح كيف فُتحت الخزانة من دون كسر، ويصل القالب بعلامة الشمع في مسرح الحادث.$q$, $q$يشرح كيف فُتحت الخزانة من دون كسر، ويصل القالب بعلامة الشمع في مسرح الحادث.$q$, $q$FACT$q$, 5, '{}'::jsonb) on conflict (id) do nothing;
insert into detective_evidence(id, scene_id, evidence_key, internal_title, public_title, public_title_ar, x, y, width, height, public_description, public_description_ar, admin_explanation, admin_explanation_ar, classification, importance, unlock_rule) values ('9af370a7-f69f-5dae-b84c-bbfb5aa2db70', '6714c33e-a448-5bd9-9aec-660daebc7f57', $q$restorer_gloves$q$, $q$Turquoise pigment on the gloves$q$, $q$Turquoise pigment on the gloves$q$, $q$صبغة فيروزية على القفازات$q$, 47, 58, 16, 12, $q$على القفازات بقعة من صبغة فيروزية تُستخدم في ترميم الإطارات، لا أثرًا من حجر الخاتم.$q$, $q$على القفازات بقعة من صبغة فيروزية تُستخدم في ترميم الإطارات، لا أثرًا من حجر الخاتم.$q$, $q$قرينة مضللة تفسّر وجود الصبغة مع أمينة. لا تثبت حيازتها للخاتم ولا تربطها بفتح الخزانة.$q$, $q$قرينة مضللة تفسّر وجود الصبغة مع أمينة. لا تثبت حيازتها للخاتم ولا تربطها بفتح الخزانة.$q$, $q$OBSERVATION$q$, 3, '{}'::jsonb) on conflict (id) do nothing;
insert into detective_evidence(id, scene_id, evidence_key, internal_title, public_title, public_title_ar, x, y, width, height, public_description, public_description_ar, admin_explanation, admin_explanation_ar, classification, importance, unlock_rule) values ('f6ffb89f-13e4-5e4b-8a4c-a71f13b9778d', '6714c33e-a448-5bd9-9aec-660daebc7f57', $q$altered_manifest$q$, $q$The amended dispatch manifest$q$, $q$The amended dispatch manifest$q$, $q$كشف الشحن المعدّل$q$, 56, 67, 26, 27, $q$تُظهر نسخة الكربون أن خانة وقت خروج الصندوق عُدّلت من 9:30 إلى 8:50، وبجوار التعديل الحرفان «ن.ف»؛ وهما يطابقان توقيع استلام نبيل في سجل الجرد. وعلى ظهرها طلب تقييم للخاتم من تاجر مجوهرات وتذكير بدين شخصي باسم نبيل.$q$, $q$تُظهر نسخة الكربون أن خانة وقت خروج الصندوق عُدّلت من 9:30 إلى 8:50، وبجوار التعديل الحرفان «ن.ف»؛ وهما يطابقان توقيع استلام نبيل في سجل الجرد. وعلى ظهرها طلب تقييم للخاتم من تاجر مجوهرات وتذكير بدين شخصي باسم نبيل.$q$, $q$يربط نبيل بمحاولة إخراج الصندوق قبل موعد الشحنة الرسمي، ويوفر قرينة على الدافع المالي. يجب جمع هذا مع دليل الخزانة والشحنة، لا اعتباره حاسمًا وحده.$q$, $q$يربط نبيل بمحاولة إخراج الصندوق قبل موعد الشحنة الرسمي، ويوفر قرينة على الدافع المالي. يجب جمع هذا مع دليل الخزانة والشحنة، لا اعتباره حاسمًا وحده.$q$, $q$FACT$q$, 5, '{}'::jsonb) on conflict (id) do nothing;
insert into detective_scenes(id, version_id, position, title, title_ar, image_path, introduction, introduction_ar) values ('b8cc6432-cce1-5d8f-900a-76aba8463fbb', '99adb141-768d-5e89-b4cc-ec444728b6b5', 3, $q$The Service Courtyard$q$, $q$ساحة الخدمة الخلفية$q$, 'demo/detective/blue-ring-heist/scene-3.webp', $q$A trolley waits beside the service gate. The crate is not empty, and its route marks lead back toward the gallery rather than out to the street.$q$, $q$توجد عربة بجوار بوابة الخدمة. الصندوق ليس فارغًا، وآثار العجلات تعود باتجاه المعرض بدلًا من الخروج إلى الشارع.$q$) on conflict (id) do nothing;
insert into detective_evidence(id, scene_id, evidence_key, internal_title, public_title, public_title_ar, x, y, width, height, public_description, public_description_ar, admin_explanation, admin_explanation_ar, classification, importance, unlock_rule) values ('18b54401-0840-523b-b81f-bf0c6d49a9d2', 'b8cc6432-cce1-5d8f-900a-76aba8463fbb', $q$ring_in_crate$q$, $q$The Blue Nile Ring in the crate$q$, $q$The Blue Nile Ring in the crate$q$, $q$خاتم النيل الأزرق داخل الصندوق$q$, 33, 55, 13, 9, $q$الخاتم ملفوف داخل بطانة مزدوجة في قاع الصندوق. لم يتضرر، لكنه كان مخفيًا ليغادر مع الشحنة.$q$, $q$الخاتم ملفوف داخل بطانة مزدوجة في قاع الصندوق. لم يتضرر، لكنه كان مخفيًا ليغادر مع الشحنة.$q$, $q$يثبت مكان الخاتم وخطة نقله خارج المبنى. لا يعني العثور عليه أن شركة الشحن أو السائق هما الفاعلان.$q$, $q$يثبت مكان الخاتم وخطة نقله خارج المبنى. لا يعني العثور عليه أن شركة الشحن أو السائق هما الفاعلان.$q$, $q$FACT$q$, 5, '{}'::jsonb) on conflict (id) do nothing;
