insert into detective_questions(id, version_id, stage_id, question_type, prompt, prompt_ar, options, answer_key, accepted_alternatives, explanation, explanation_ar, associated_evidence, points, penalty, position) values ('ef330bfc-4e8d-507a-866e-b047204c3130', '99adb141-768d-5e89-b4cc-ec444728b6b5', 'da207508-7464-5f3e-a627-6d9960ff2673', $q$MULTIPLE_CHOICE$q$, $q$رتّب ما حدث من الأسبق إلى الأحدث. اختر الترتيب الصحيح.$q$, $q$رتّب ما حدث من الأسبق إلى الأحدث. اختر الترتيب الصحيح.$q$, $q$[{"id":"a","text":"Cabinet opened with a copied key → Ring hidden in the false-bottom crate → Crate moved to the service courtyard → Hossam arrived and found it before pickup","text_ar":"فُتحت الخزانة بمفتاح منسوخ ← أُخفي الخاتم في قاع الصندوق المزدوج ← نُقل الصندوق إلى ساحة الخدمة ← وصل حسام فوجده قبل موعد الاستلام"},{"id":"b","text":"Ring hidden in the false-bottom crate → Cabinet opened with a copied key → Crate moved to the service courtyard → Hossam arrived and found it before pickup","text_ar":"أُخفي الخاتم في قاع الصندوق المزدوج ← فُتحت الخزانة بمفتاح منسوخ ← نُقل الصندوق إلى ساحة الخدمة ← وصل حسام فوجده قبل موعد الاستلام"},{"id":"c","text":"Ring hidden in the false-bottom crate → Crate moved to the service courtyard → Hossam arrived and found it before pickup → Cabinet opened with a copied key","text_ar":"أُخفي الخاتم في قاع الصندوق المزدوج ← نُقل الصندوق إلى ساحة الخدمة ← وصل حسام فوجده قبل موعد الاستلام ← فُتحت الخزانة بمفتاح منسوخ"},{"id":"d","text":"Hossam arrived and found it before pickup → Crate moved to the service courtyard → Ring hidden in the false-bottom crate → Cabinet opened with a copied key","text_ar":"وصل حسام فوجده قبل موعد الاستلام ← نُقل الصندوق إلى ساحة الخدمة ← أُخفي الخاتم في قاع الصندوق المزدوج ← فُتحت الخزانة بمفتاح منسوخ"}]$q$::jsonb, $q${"option_id":"a"}$q$::jsonb, '[]'::jsonb, $q$يشرح كيف فُتحت الخزانة من دون كسر، ويصل القالب بعلامة الشمع في مسرح الحادث.$q$, $q$يشرح كيف فُتحت الخزانة من دون كسر، ويصل القالب بعلامة الشمع في مسرح الحادث.$q$, array['598d6995-3324-5a56-b0a2-81b4771b2df9'::uuid,'18b54401-0840-523b-b81f-bf0c6d49a9d2'::uuid,'f24d150d-7983-5e70-963f-9444c35a67a8'::uuid]::uuid[], 20, -5, 1) on conflict (id) do nothing;
insert into detective_questions(id, version_id, stage_id, question_type, prompt, prompt_ar, options, answer_key, accepted_alternatives, explanation, explanation_ar, associated_evidence, points, penalty, position) values ('fbad7ca4-0b7f-5735-9ada-a3e4f48aa1b0', '99adb141-768d-5e89-b4cc-ec444728b6b5', 'da207508-7464-5f3e-a627-6d9960ff2673', $q$SUSPECT_SELECTION$q$, $q$من الشخص الذي تدعمه الأدلة بوصفه من أخذ الخاتم؟$q$, $q$من الشخص الذي تدعمه الأدلة بوصفه من أخذ الخاتم؟$q$, $q$[{"id":"a","text":"Nabil Fouad","text_ar":"نبيل فؤاد"},{"id":"b","text":"Amina Hassan","text_ar":"أمينة حسن"},{"id":"c","text":"Hossam Eid","text_ar":"حسام عيد"}]$q$::jsonb, $q${"option_id":"a"}$q$::jsonb, '[]'::jsonb, $q$تربط نبيل مباشرة بنقل الصندوق في الوقت الذي ادعى فيه أنه لم يقترب من المعرض بعد إغلاقه.$q$, $q$تربط نبيل مباشرة بنقل الصندوق في الوقت الذي ادعى فيه أنه لم يقترب من المعرض بعد إغلاقه.$q$, array['83aea0fc-9895-5152-af8e-b69646540b6b'::uuid,'f6ffb89f-13e4-5e4b-8a4c-a71f13b9778d'::uuid,'9a5fc7de-c8f9-58d8-b4ea-c60d191aedba'::uuid]::uuid[], 20, -5, 2) on conflict (id) do nothing;
insert into detective_questions(id, version_id, stage_id, question_type, prompt, prompt_ar, options, answer_key, accepted_alternatives, explanation, explanation_ar, associated_evidence, points, penalty, position) values ('df4a8572-6d05-5c50-a930-611412d4a4f8', '99adb141-768d-5e89-b4cc-ec444728b6b5', 'da207508-7464-5f3e-a627-6d9960ff2673', $q$FINAL_CONCLUSION$q$, $q$ما التفسير الأفضل لاختفاء خاتم النيل الأزرق؟$q$, $q$ما التفسير الأفضل لاختفاء خاتم النيل الأزرق؟$q$, $q$[{"id":"a","text":"Nabil copied the cabinet key, took the ring, hid it in the outgoing crate and changed the dispatch time to sell it and repay his debt","text_ar":"نسخ نبيل المفتاح، وأخذ الخاتم وأخفاه في صندوق الشحن، ثم غيّر موعد الخروج ليبيعه ويسدد دينه"},{"id":"b","text":"Amina accidentally packed the ring with her restoration tools","text_ar":"وضعت أمينة الخاتم بالخطأ مع أدوات الترميم"},{"id":"c","text":"Hossam stole it after arriving at the courtyard","text_ar":"سرقه حسام بعد وصوله إلى الساحة"}]$q$::jsonb, $q${"option_id":"a"}$q$::jsonb, '[]'::jsonb, $q$لم يغادر خاتم النيل الأزرق المعرض. نسخ نبيل فؤاد مفتاح الخزانة في ورشة الترميم، وفتحها من دون كسر، ثم خبّأ الخاتم في قاع صندوق شحن مزدوج. غيّر موعد خروج الصندوق ووقّع استلامه على أنه نقل مؤقت، على أمل بيعه لتسديد دينه. لكنه ترك سلسلة أدلة: طبعة المفتاح والشمع الأزرق، توقيعه بعد الوقت الذي ادعى فيه المغادرة، كشف الشحن المعدّل، والملصق الذي يحمل اسمه. عُثر على الخاتم قبل وصول السائق إلى موعد الاستلام. أمينة لم تسرقه؛ صبغة قفازاتها جزء من عمل الترميم، وحسام وصل بعد نقل الصندوق.$q$, $q$لم يغادر خاتم النيل الأزرق المعرض. نسخ نبيل فؤاد مفتاح الخزانة في ورشة الترميم، وفتحها من دون كسر، ثم خبّأ الخاتم في قاع صندوق شحن مزدوج. غيّر موعد خروج الصندوق ووقّع استلامه على أنه نقل مؤقت، على أمل بيعه لتسديد دينه. لكنه ترك سلسلة أدلة: طبعة المفتاح والشمع الأزرق، توقيعه بعد الوقت الذي ادعى فيه المغادرة، كشف الشحن المعدّل، والملصق الذي يحمل اسمه. عُثر على الخاتم قبل وصول السائق إلى موعد الاستلام. أمينة لم تسرقه؛ صبغة قفازاتها جزء من عمل الترميم، وحسام وصل بعد نقل الصندوق.$q$, array['af567bc3-d75f-545a-a963-a7e9d94c3608'::uuid,'6248b016-e73b-5509-89e0-23104f2ecdb5'::uuid,'598d6995-3324-5a56-b0a2-81b4771b2df9'::uuid,'83aea0fc-9895-5152-af8e-b69646540b6b'::uuid,'f6ffb89f-13e4-5e4b-8a4c-a71f13b9778d'::uuid,'18b54401-0840-523b-b81f-bf0c6d49a9d2'::uuid,'9a5fc7de-c8f9-58d8-b4ea-c60d191aedba'::uuid,'f24d150d-7983-5e70-963f-9444c35a67a8'::uuid]::uuid[], 25, -5, 3) on conflict (id) do nothing;
insert into detective_suspects(id, version_id, name, name_ar, description, description_ar, relationship, background, timeline, alibi) values ('593cb553-efca-5068-9aff-ad2bbdba717f', '99adb141-768d-5e89-b4cc-ec444728b6b5', $q$Nabil Fouad$q$, $q$نبيل فؤاد$q$, $q$يعرف ترتيب القاعة وسجل الجرد، ويمكنه دخول الورشة وساحة الخدمة.$q$, $q$يعرف ترتيب القاعة وسجل الجرد، ويمكنه دخول الورشة وساحة الخدمة. كان مسؤولًا عن تجهيز الشحنات المسائية. يحتاج إلى المال بعد تراكم دين شخصي، لكنه أنكر أن يكون قد لمس صندوق الخاتم.$q$, $q$مساعد المعرض$q$, $q$Gallery assistant$q$, $q${"20:00":"قال إنه غادر","20:42":"وقّع استلامًا داخليًا للصندوق","20:50":"عُدّل موعد خروج الصندوق إلى هذا الوقت"}$q$::jsonb, $q$قال إنه غادر قبل الثامنة ولم يقترب من الخزانة أو عربة الشحن بعدها.$q$) on conflict (id) do nothing;
insert into detective_suspects(id, version_id, name, name_ar, description, description_ar, relationship, background, timeline, alibi) values ('d7f66b04-a6d8-5122-9808-65ab28134b0a', '99adb141-768d-5e89-b4cc-ec444728b6b5', $q$Amina Hassan$q$, $q$أمينة حسن$q$, $q$تعمل على الإطارات القديمة وتستخدم الشمع والصبغات الفيروزية في الترميم.$q$, $q$تعمل على الإطارات القديمة وتستخدم الشمع والصبغات الفيروزية في الترميم. أنهت عملها في الورشة قبل إغلاق المعرض، وسلمت أدواتها في سجل الورشة.$q$, $q$مرمّمة الآثار$q$, $q$Restoration conservator$q$, $q${"19:00":"انتهاء عملها المسجل","19:30":"وقت مغادرتها الذي ذكرته"}$q$::jsonb, $q$قالت إنها غادرت عند السابعة والنصف، ولم تعد بعد ذلك.$q$) on conflict (id) do nothing;
insert into detective_suspects(id, version_id, name, name_ar, description, description_ar, relationship, background, timeline, alibi) values ('e41604c0-a601-5de0-b640-d0deaadcd18b', '99adb141-768d-5e89-b4cc-ec444728b6b5', $q$Hossam Eid$q$, $q$حسام عيد$q$, $q$ينقل الصناديق بين المعرض والمخزن، ويستخدم العربة الظاهرة في الساحة.$q$, $q$ينقل الصناديق بين المعرض والمخزن، ويستخدم العربة الظاهرة في الساحة. جاء لاستلام شحنة أدوات ترميم مقررة في التاسعة والنصف.$q$, $q$سائق الشحن$q$, $q$Courier$q$, $q${"21:05":"وصوله المسجل إلى البوابة","21:30":"موعد استلام الشحنة الأصلي"}$q$::jsonb, $q$قال إنه وصل بعد التاسعة، ووجد الصندوق مغلقًا؛ لم يفتح الصندوق ولم يغادر به.$q$) on conflict (id) do nothing;
insert into detective_statements(id, suspect_id, statement, statement_ar, truth_status, conflicting_evidence, admin_explanation, admin_explanation_ar) values ('ce2f7f52-6059-51ff-a2d9-bece8cc2eeb9', '593cb553-efca-5068-9aff-ad2bbdba717f', $q$غادرت قبل الثامنة، ولم أقترب من الخزانة أو صندوق الشحن بعد ذلك.$q$, $q$غادرت قبل الثامنة، ولم أقترب من الخزانة أو صندوق الشحن بعد ذلك.$q$, $q$FALSE$q$, array['83aea0fc-9895-5152-af8e-b69646540b6b'::uuid,'f6ffb89f-13e4-5e4b-8a4c-a71f13b9778d'::uuid,'9a5fc7de-c8f9-58d8-b4ea-c60d191aedba'::uuid]::uuid[], $q$التوقيع الداخلي عند 8:42 وتعديل وقت الشحنة وملصق الصندوق باسمه تناقض قوله.$q$, $q$التوقيع الداخلي عند 8:42 وتعديل وقت الشحنة وملصق الصندوق باسمه تناقض قوله.$q$) on conflict (id) do nothing;
insert into detective_statements(id, suspect_id, statement, statement_ar, truth_status, conflicting_evidence, admin_explanation, admin_explanation_ar) values ('5af9d358-e831-5d91-bfb8-925b8214bf8e', 'd7f66b04-a6d8-5122-9808-65ab28134b0a', $q$كنت أستخدم الشمع والصبغة في ترميم إطار، وغادرت قبل الثامنة. القفازات لي، لكنني لم ألمس الخاتم.$q$, $q$كنت أستخدم الشمع والصبغة في ترميم إطار، وغادرت قبل الثامنة. القفازات لي، لكنني لم ألمس الخاتم.$q$, $q$TRUE$q$, array['9af370a7-f69f-5dae-b84c-bbfb5aa2db70'::uuid]::uuid[], $q$تفسيرها يطابق عملها المسجل؛ الصبغة على القفازات قرينة مضللة وليست أثرًا من الحجر.$q$, $q$تفسيرها يطابق عملها المسجل؛ الصبغة على القفازات قرينة مضللة وليست أثرًا من الحجر.$q$) on conflict (id) do nothing;
insert into detective_statements(id, suspect_id, statement, statement_ar, truth_status, conflicting_evidence, admin_explanation, admin_explanation_ar) values ('c5a2df61-855c-5436-822f-83bdf261826f', 'e41604c0-a601-5de0-b640-d0deaadcd18b', $q$لم أصل إلا بعد التاسعة. وجدت الصندوق مقفولًا في الساحة ولم أحمله إلى الشارع.$q$, $q$لم أصل إلا بعد التاسعة. وجدت الصندوق مقفولًا في الساحة ولم أحمله إلى الشارع.$q$, $q$TRUE$q$, array['18b54401-0840-523b-b81f-bf0c6d49a9d2'::uuid,'f24d150d-7983-5e70-963f-9444c35a67a8'::uuid]::uuid[], $q$وقت البوابة يؤكد وصوله بعد أن وُضع الصندوق. آثار العربة تحركت داخل الساحة لا إلى الشارع.$q$, $q$وقت البوابة يؤكد وصوله بعد أن وُضع الصندوق. آثار العربة تحركت داخل الساحة لا إلى الشارع.$q$) on conflict (id) do nothing;
