insert into detective_hints(id, version_id, stage_id, hint_text, hint_text_ar, unlock_rule, penalty, position) values ('6f74b1f5-30c4-5290-9749-9f4fe5bfded7', '99adb141-768d-5e89-b4cc-ec444728b6b5', 'f8ea9475-0f65-5695-bc9e-52d9ae2f883f', $q$ابدأ بالسؤال: هل الخزانة مكسورة فعلًا، أم فُتحت بطريقة أخرى؟$q$, $q$ابدأ بالسؤال: هل الخزانة مكسورة فعلًا، أم فُتحت بطريقة أخرى؟$q$, '{}'::jsonb, -2, 1) on conflict (id) do nothing;
insert into detective_hints(id, version_id, stage_id, hint_text, hint_text_ar, unlock_rule, penalty, position) values ('3e6a7211-81f1-5273-bb94-bf3629912839', '99adb141-768d-5e89-b4cc-ec444728b6b5', '6e3a532e-81d2-590d-ae9e-abc6041efc59', $q$لا تتهم صاحب القفازات لمجرد وجود لون مشابه؛ قارن نوع الصبغة ببقية الأدلة.$q$, $q$لا تتهم صاحب القفازات لمجرد وجود لون مشابه؛ قارن نوع الصبغة ببقية الأدلة.$q$, '{}'::jsonb, -3, 2) on conflict (id) do nothing;
insert into detective_hints(id, version_id, stage_id, hint_text, hint_text_ar, unlock_rule, penalty, position) values ('f176f9cd-333e-5040-9e53-b939a86908d4', '99adb141-768d-5e89-b4cc-ec444728b6b5', 'da207508-7464-5f3e-a627-6d9960ff2673', $q$اجمع بين وقت التوقيع، واسم المرسل على الملصق، والخاتم داخل الصندوق.$q$, $q$اجمع بين وقت التوقيع، واسم المرسل على الملصق، والخاتم داخل الصندوق.$q$, '{}'::jsonb, -4, 3) on conflict (id) do nothing;
insert into detective_solutions(id, version_id, public_reveal, public_reveal_ar, solution_key, alternative_hypotheses, educational_explanation, educational_explanation_ar) values ('14ba25ab-fd74-51aa-96cf-7447108896ca', '99adb141-768d-5e89-b4cc-ec444728b6b5', $q$لم يغادر خاتم النيل الأزرق المعرض. نسخ نبيل فؤاد مفتاح الخزانة في ورشة الترميم، وفتحها من دون كسر، ثم خبّأ الخاتم في قاع صندوق شحن مزدوج. غيّر موعد خروج الصندوق ووقّع استلامه على أنه نقل مؤقت، على أمل بيعه لتسديد دينه. لكنه ترك سلسلة أدلة: طبعة المفتاح والشمع الأزرق، توقيعه بعد الوقت الذي ادعى فيه المغادرة، كشف الشحن المعدّل، والملصق الذي يحمل اسمه. عُثر على الخاتم قبل وصول السائق إلى موعد الاستلام. أمينة لم تسرقه؛ صبغة قفازاتها جزء من عمل الترميم، وحسام وصل بعد نقل الصندوق.$q$, $q$لم يغادر خاتم النيل الأزرق المعرض. نسخ نبيل فؤاد مفتاح الخزانة في ورشة الترميم، وفتحها من دون كسر، ثم خبّأ الخاتم في قاع صندوق شحن مزدوج. غيّر موعد خروج الصندوق ووقّع استلامه على أنه نقل مؤقت، على أمل بيعه لتسديد دينه. لكنه ترك سلسلة أدلة: طبعة المفتاح والشمع الأزرق، توقيعه بعد الوقت الذي ادعى فيه المغادرة، كشف الشحن المعدّل، والملصق الذي يحمل اسمه. عُثر على الخاتم قبل وصول السائق إلى موعد الاستلام. أمينة لم تسرقه؛ صبغة قفازاتها جزء من عمل الترميم، وحسام وصل بعد نقل الصندوق.$q$, $q${"final_question":"df4a8572-6d05-5c50-a930-611412d4a4f8"}$q$::jsonb, $q$[{"en":"Amina took the ring because her gloves had turquoise pigment.","ar":"أمينة أخذت الخاتم لأن على قفازاتها صبغة فيروزية.","why_wrong_en":"الصبغة مستخدمة في الترميم، ولا تربط أمينة بتوقيع نقل الصندوق أو بتغيير موعد الشحنة أو بالملصق الذي يحمل اسم نبيل.","why_wrong_ar":"الصبغة مستخدمة في الترميم، ولا تربط أمينة بتوقيع نقل الصندوق أو بتغيير موعد الشحنة أو بالملصق الذي يحمل اسم نبيل."},{"en":"Hossam stole the ring after arriving in the courtyard.","ar":"حسام سرق الخاتم عندما وصل إلى الساحة.","why_wrong_en":"وقت البوابة يثبت وصوله بعد نقل الصندوق، وآثار العربة تعود إلى الداخل، والخاتم كان مخفيًا قبل موعد استلامه.","why_wrong_ar":"وقت البوابة يثبت وصوله بعد نقل الصندوق، وآثار العربة تعود إلى الداخل، والخاتم كان مخفيًا قبل موعد استلامه."}]$q$::jsonb, $q$حل القضية يعتمد على تجميع أدلة مستقلة لا على دليل واحد: سلامة الخزانة تشير إلى استخدام مفتاح، وطبعة المفتاح تتصل بالشمع الأزرق؛ سجل الجرد وكشف الشحن يناقضان أقوال نبيل؛ وملصق الصندوق يربط اسمه بالصندوق الذي وُجد فيه الخاتم. أقوال أمينة وحسام متوافقة مع التوقيت، لذا فالصبغة وآثار العربة قرائن مضللة عند فصلها عن السياق. لا توجد إصابة أو عنف؛ إنها قضية سرقة واسترداد ممتلكات.$q$, $q$حل القضية يعتمد على تجميع أدلة مستقلة لا على دليل واحد: سلامة الخزانة تشير إلى استخدام مفتاح، وطبعة المفتاح تتصل بالشمع الأزرق؛ سجل الجرد وكشف الشحن يناقضان أقوال نبيل؛ وملصق الصندوق يربط اسمه بالصندوق الذي وُجد فيه الخاتم. أقوال أمينة وحسام متوافقة مع التوقيت، لذا فالصبغة وآثار العربة قرائن مضللة عند فصلها عن السياق. لا توجد إصابة أو عنف؛ إنها قضية سرقة واسترداد ممتلكات.$q$) on conflict (id) do nothing;
